  "_Sesiones_Video", "_Informe_Tiempos",
  "_Miembros_Familia", "_Tokens_Invitacion", "_Listas_Familia", "_Listas_Videos",
  "_Historial_Efectividad", "_Reglas_Bonos", "_Historial_Bonos", "_Datos_Privados_Usuarios",
  "_Tareas_Pendientes"
];

/** [OPT-10] Parámetros de la cola de tareas diferidas. */
const COLA_MAX_INTENTOS = 5;
const COLA_ESPERA_BASE_MIN = 30;      // 30 min, 1 h, 2 h, 4 h, 8 h
const COLA_LOTE_POR_EJECUCION = 25;
const ESTADO_TAREA = { EN_PROCESO: "EN_PROCESO", PENDIENTE: "PENDIENTE", COMPLETADA: "COMPLETADA", AGOTADA: "AGOTADA", CANCELADA: "CANCELADA" };

/** Hojas que NUNCA deben exponerse por ningún endpoint. */
const HOJAS_CONFIDENCIALES = ["_Claves_Examenes", "_Datos_Privados_Usuarios", "_Tokens_Invitacion"];

/**
Corta la lectura si alguien pide una de las hojas de arriba por un camino
genérico. Hoy ninguna ruta del portal acepta el nombre de una hoja, así que
esta guarda no rechaza nada: existe para que el día que alguien añada un
lector parametrizado —y ese es justo el atajo que se toma con prisa— la regla
esté escrita en el código y no solo en una lista que nadie consulta.

Caché de idioma por ejecución: evita golpear ScriptProperties dentro de bucles. */
let _CACHE_IDIOMA = null;

/** Idioma forzado para el bloque en curso. Ver `conIdiomaDe()`. */
let _IDIOMA_FORZADO = null;

const IDIOMAS_SOPORTADOS = ["ES", "EN"];

function normalizarIdioma(valor) {
  const v = (valor || "").toString().trim().toUpperCase().slice(0, 2);
  return IDIOMAS_SOPORTADOS.indexOf(v) !== -1 ? v : "";
}

/** Clave donde vive la preferencia de idioma de una persona.

Caché de idioma por ejecución: evita golpear ScriptProperties dentro de bucles. */
let _CACHE_IDIOMA = null;

/** Idioma forzado para el bloque en curso. Ver `conIdiomaDe()`. */
let _IDIOMA_FORZADO = null;

