  return IDIOMAS_SOPORTADOS.indexOf(v) !== -1 ? v : "";
}

/** Clave donde vive la preferencia de idioma de una persona. */
function claveIdiomaDe(email) {
  return "LANG_" + Utilities.base64Encode((email || "").toString().toLowerCase()).slice(0, 40);
}

/**
Idioma en el que hay que escribir AHORA MISMO.

Tres niveles, de más específico a más general:
  1. El que haya forzado `conIdiomaDe()` — un correo dirigido a alguien
     concreto se escribe en SU idioma, no en el de quien lanzó el proceso.
  2. La preferencia guardada de esa persona, si se pasa su correo.
  3. El idioma del script, que es el del menú de la hoja.

