una incidencia, el motivo de una sugerencia. `sanitizarEntrada` quita comillas
y caracteres de control, pero deja pasar `<script>`; y esos textos aterrizan en
el panel del administrador, así que un colaborador podría dejarle ahí una
etiqueta preparada. El portal escapa al pintar, pero eso es una sola capa: si
mañana alguien pinta ese campo con innerHTML en otra pantalla, el fallo vuelve.
Aquí se quitan los ángulos de una vez, que en prosa no se pierde nada.

No se usa para las notas privadas: esas solo las lee quien las escribe, y ahí
«a < b» es texto legítimo que nadie tiene por qué perder.
/
function sanitizarTextoUsuario(texto) {
  return sanitizarEntrada(texto).replace(/[<>]/g, "");
}

/** Escapa metacaracteres antes de construir una expresión regular dinámica. */
function escapeRegExp(cadena) {
  return (cadena || "").toString().replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Convierte "07:54" o "1:07:54" a segundos. Devuelve 0 si no reconoce el formato. */
function convertirTimestampASegundos(valor) {
  if (valor === null || valor === undefined || valor === "") return 0;
  if (typeof valor === "number") return Math.max(0, Math.floor(valor));
  const partes = valor.toString().trim().split(":").map(p => parseInt(p, 10));
  if (partes.some(isNaN)) {
    const n = parseInt(valor, 10);
    return isNaN(n) ? 0 : Math.max(0, n);
  }
  if (partes.length === 3) return partes[0] * 3600 + partes[1] * 60 + partes[2];
  if (partes.length === 2) return partes[0] * 60 + partes[1];
  return Math.max(0, partes[0] || 0);
}

/** Convierte segundos a "mm:ss" o "h:mm:ss".

Limpia comillas, controles y saltos de línea de cualquier entrada externa. */
function sanitizarEntrada(texto) {
  if (texto === null || texto === undefined) return "";
  return texto.toString()
    .replace(/['"]/g, "")
    .replace(/[\x00-\x1F\x7F]/g, "")
    .replace(/\n/g, " ")
    .trim();
}

