Elimina de la cola las tareas ya completadas. Se llama en el mantenimiento. */
function purgarTareasCompletadas() {
  exigirOrigenInterno("purgarTareasCompletadas");
  const reserva = reservarConsumidorCola_();
  if (!reserva) return 0;
  try {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("_Tareas_Pendientes");
  if (!sheet || sheet.getLastRow() < 2) return 0;
  const estados = sheet.getRange(2, COLA.ESTADO + 1, sheet.getLastRow() - 1, 1).getValues();
  let borradas = 0;
  for (let i = estados.length - 1; i >= 0; i--) {
    if (estados[i][0] === ESTADO_TAREA.COMPLETADA || estados[i][0] === ESTADO_TAREA.CANCELADA) {
      sheet.deleteRow(i + 2);
      borradas++;
    }
  }
  if (borradas > 0) logInfo("Cola", `Purgadas ${borradas} tareas resueltas.`);
  return borradas;
  } finally { liberarConsumidorCola_(reserva); }
}

