    Utilities.sleep(Math.min(CANJE_RETARDO_BASE_MS * Math.pow(2, fallos - 1), CANJE_RETARDO_MAX_MS));
    return fallos;
  } catch (e) {
    return 0;   // sin caché no hay freno, pero tampoco se cierra la entrada
  }
}

