function verificarYEstructurarHojasConfig(silencioso = true) {
  let reparadas = 0;
  Object.keys(ESQUEMAS_HOJAS).forEach(nombre => {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const existia = Boolean(ss.getSheetByName(nombre));
    try {
      asegurarHojaSistema(nombre);
      if (!existia) reparadas++;
    } catch (e) {
      logError("Config", `No se pudo asegurar ${nombre}: ${e.message}`);
    }
  });

  // Semillas enriquecidas que no caben en una tabla plana.
  crearPestanaConfigPrompts();
  crearPestanaConfigTaxonomia();

  // [F0-2] Migración del banco de preguntas si hace falta.
  try { migrarBancoPreguntas(true); } catch (e) { logError("Migración", e.message); }

  /* [v2.6.10] El filtro de la fila 1. Va aquí y no en un botón que haya que
     acordarse de pulsar, porque su momento de romperse es justo el que nadie
     mira: al importar filas nuevas el filtro se queda cubriendo el rango viejo,
     y a partir de ahí filtrar «Alcance = Pendiente» deja fuera las últimas
     importadas sin avisar de nada. Es no-operación cuando ya está bien, así que
     no cuesta nada en cada apertura. */
  try { asegurarFiltroCatalogo(); } catch (e) { logWarn("Filtro", e.message); }

  if (!silencioso && reparadas > 0) {
