quien la pega sabe de dónde la sacó, y eso queda registrado en `letraFuente`.
/
function guardarLetraVideo(videoId, letra, fuente) {
  const texto = (letra || "").toString().trim();
  if (!videoId || !texto) return "";
  return persistirTextoPesado(videoId, "", null, {
    letra: texto.slice(0, 40000),
    letraFuente: (fuente || "").toString().trim().slice(0, 120),
    letraFecha: formatearFecha(new Date())
  });
}

function recuperarTextoPesado_(archivoId) {
  exigirOrigenInterno("recuperarTextoPesado_");
  if (!archivoId || !archivoId.toString().trim()) return "";
  try {
    const archivo = DriveApp.getFileById(archivoId.toString().trim());
    const data = JSON.parse(archivo.getBlob().getDataAsString());
    return data.contenido || "";
  } catch (e) {
    logWarn("Drive RAG", `No se pudo leer el documento ${archivoId}: ${e.message}`);
    return "[Error al leer archivo RAG de Drive: " + e.message + "]";
  }
}

