/**
Lo que parsearVideoUniversal() sabe reconocer, en el orden en que lo intenta.
Está aquí para poder DECÍRSELO a quien pega una URL que no encaja: un
"URL inválida" a secas obliga a adivinar, y la gente acaba pegando la misma
URL tres veces en vez de darse cuenta de que ese enlace no es de video.
/
const PLATAFORMAS_ADMITIDAS = ["YouTube", "Vimeo", "TikTok", "Facebook", "Twitch", "Dailymotion"];

function obtenerHojaSugerencias() { return asegurarHojaSistema("_Sugerencias"); }

/** El mismo texto para los dos caminos: quien sugiere y quien da de alta leen lo mismo. */
function mensajeUrlNoReconocida(url) {
  return "No se reconoce «" + (url || "").toString().trim().slice(0, 120) +
    "» como un enlace de video. Se admiten: " + PLATAFORMAS_ADMITIDAS.join(", ") + ".";
}

/**
Fila (1-based, tal como se ve en la hoja) en la que ya está ese ID de video, o
0 si no está. Se lee solo la columna del ID en vez del rango completo: en un
catálogo de cientos de filas, traer las 32 columnas para mirar una es tiempo que
el portal paga en cada alta.
/
function buscarFilaDeVideoPorId(idVideo) {
  const buscado = (idVideo || "").toString().trim();
  if (!buscado) return 0;
  const hoja = obtenerHojaDatos();
  if (hoja.getLastRow() < 2) return 0;
  const ids = hoja.getRange(2, IDX.ID + 1, hoja.getLastRow() - 1, 1).getValues();
  for (let i = 0; i < ids.length; i++) {
    if ((ids[i][0] || "").toString().trim() === buscado) return i + 2;
  }
  return 0;
}

/**
Núcleo compartido del alta. Lo usan el alta directa del administrador y la
aprobación de una sugerencia: si cada una construyera su propia fila, tarde o
temprano una de las dos se olvidaría de poner SIN_CLASIFICAR o de invalidar la
caché, y el video aprobado se comportaría distinto al añadido a mano.

No lanza excepción por una URL mala ni por un duplicado: son respuestas
normales que la pantalla tiene que poder mostrar, no fallos del sistema.

@return {{exito:boolean, idVideo:string, fila:number, mensaje:string, duplicado?:boolean}}

Alta directa desde el portal. Solo administradores.
@param {string} token
@param {string} url
@param {{titulo?:string}} [opciones]
@return {{exito:boolean, idVideo:string, fila:number, mensaje:string, duplicado?:boolean}}

Alta directa desde el portal. Solo administradores.
@param {string} token
@param {string} url
@param {{titulo?:string}} [opciones]
@return {{exito:boolean, idVideo:string, fila:number, mensaje:string, duplicado?:boolean}}
