al contrario que la señal del reproductor.

Los tramos de una persona, o de todas si el correo va vacío, ordenados por inicio.

Aquí sí se lee la hoja completa: un informe se pide a mano y de vez en cuando,
al contrario que la señal del reproductor.
/
function leerTramosVisionado_(correo) {
  exigirOrigenInterno("leerTramosVisionado_");
  const salida = [];
  const hoja = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("_Sesiones_Video");
  if (!hoja || hoja.getLastRow() < 2) return salida;

  const filtro = (correo || "").toString().toLowerCase().trim();
  hoja.getRange(2, 1, hoja.getLastRow() - 1, SVID_COLS).getValues().forEach(function (f) {
    const email = (f[SVID.CORREO] || "").toString().toLowerCase().trim();
    if (!email || (filtro && email !== filtro)) return;
    const inicioMs = milisegundosDe(f[SVID.INICIO]);
    if (!inicioMs) return;
    salida.push({
      correo: email,
      videoId: (f[SVID.VIDEO] || "").toString().trim(),
      inicioMs: inicioMs,
      finMs: milisegundosDe(f[SVID.FIN]) || inicioMs,
      efectivo: parseFloat(f[SVID.EFECTIVO]) || 0,
      pausa: parseFloat(f[SVID.PAUSA]) || 0,
      avance: parseFloat(f[SVID.AVANCE]) || 0,
      senales: parseInt(f[SVID.SENALES], 10) || 0
    });
  });
  salida.sort(function (a, b) { return a.inicioMs - b.inicioMs; });
  return salida;
}

