function obtenerResumenTiempos(token, mes) {
  validarTokenConScope(token, "supervisor");
  const umbrales = umbralesMedicionTiempo_();
  const clave = /^\d{4}-\d{2}$/.test((mes || "").toString())
    ? mes.toString() : formatearFecha(new Date(), "yyyy-MM");

  let catalogo = {};
  try { catalogo = obtenerIndiceCatalogo() || {}; } catch (e) { catalogo = {}; }

  const porCorreo = agruparTiemposPorCorreo_("");
  const personas = [];
  Object.keys(porCorreo).forEach(function (email) {
    const inf = construirInformeTiempos_(
      porCorreo[email].tramos, porCorreo[email].examenes, umbrales, catalogo);
    const m = inf.meses.filter(function (x) { return x.clave === clave; })[0];
    if (!m) return;   // sin nada ese mes no ocupa una fila de la tabla
    personas.push({
      correo: email,
      nombre: resolverNombreVisible(email),
      efectivoSeg: m.efectivoSeg,
      ociosoSeg: m.ociosoSeg,
      pausaSeg: m.pausaSeg,
