    throw new Error("Esa acción no se ejecuta desde el panel.");
  }
  marcarOrigenConfiable();
  const accion = globalThis[nombre];
  if (typeof accion !== "function") throw new Error("La acción autorizada no está disponible en esta versión.");

  const previo = _PANEL_SALIDA;
  _PANEL_SALIDA = [];
  try {
    accion();
    const dichos = _PANEL_SALIDA.filter(Boolean);
    logInfo("Panel", "Acción ejecutada desde el panel: " + nombre);
    return { ejecutada: true, mensaje: dichos.length ? dichos.join("\n\n") : "Hecho." };
