    if (e && e.necesitaMenu) {
      /* La lista estaba desactualizada: se deja elegida para el menú en vez de
         dejar al usuario con un error que no le dice qué hacer. */
      PropertiesService.getUserProperties().setProperty("ACCION_MENU_PENDIENTE_R7",
