function aplicarMarca(m) {
  if (!m) return;
  Object.keys(MARCA).forEach(function (k) {
    if (m[k] === undefined || m[k] === null) return;
    if (MARCA_VACIABLES.indexOf(k) !== -1) { MARCA[k] = m[k]; return; }
    if (m[k] !== "") MARCA[k] = m[k];
  });

  const sig = MARCA.logoUrl
    ? '<img src="' + esc(MARCA.logoUrl) + '" alt="">'
    : esc(MARCA.iniciales);

  const cab = document.getElementById("marca-sig");
  if (cab) cab.innerHTML = sig;
  const nom = document.getElementById("marca-nombre");
  if (nom) nom.textContent = MARCA.nombre;

