/* Un único sitio donde se enlazan las tarjetas, para las tres pantallas que las
   pintan. Cuando esto estaba repetido, añadir algo a la tarjeta significaba
   acordarse de tocar tres bloques idénticos, y el tercero se quedaba atrás. */
function enlazarTarjetas(cont) {
  cont.querySelectorAll(".v-tarjeta").forEach(function (b) {
    b.addEventListener("click", function (ev) {
      // La estrella vive dentro de la tarjeta: sin esto, marcar favorito
      // abriría el video además de marcarlo.
      const est = ev.target.closest(".estrella");
      if (est) { ev.stopPropagation(); alternarEstrella(est); return; }
      abrirVideo(JSON.parse(b.getAttribute("data-video")));
    });
    // La tarjeta ya no es un <button>, así que el teclado hay que devolvérselo.
    b.addEventListener("keydown", function (ev) {
      if (ev.target.closest(".estrella")) return;      // el botón se apaña solo
      if (ev.key !== "Enter" && ev.key !== " ") return;
      ev.preventDefault();
      abrirVideo(JSON.parse(b.getAttribute("data-video")));
    });
  });
}


/* ---------- Diagnóstico ----------
   Cuando algo no carga, el usuario no tiene forma de saber si falta configurar
   una clave, si la hoja está vacía o si la implementación quedó desactualizada.
   Esto lo responde en una pantalla, sin abrir la hoja ni el registro.

Un solo oyente sobre el contenedor, que sobrevive a los repintados.

Aquí había un `addEventListener` por cada carga de la vista, y el contenedor
no se destruye entre cargas: solo se le reemplaza el contenido. A la segunda
visita había dos oyentes, y el clic en «Ver el contenido» se atendía dos
veces — abrir y volver a cerrar en el mismo gesto—, así que el botón parecía
muerto. Con tres volvía a funcionar, y con cuatro no: el síntoma iba y venía
según cuántas veces hubieras entrado, que es la peor forma de un fallo.
/
function enlazarModulos(cont, mods) {
  MODULOS_PINTADOS = {};
  mods.forEach(function (m) { MODULOS_PINTADOS[m.moduloId] = m; });
  if (cont.dataset.enlazado) return;
  cont.dataset.enlazado = "1";

  cont.addEventListener("click", function (ev) {
    const bEx = ev.target.closest("[data-examen]");
    if (bEx) { irA("#/examen?mod=" + encodeURIComponent(bEx.getAttribute("data-examen"))); return; }

    const bInf = ev.target.closest("[data-informe]");
    if (bInf) { irA("#/informe?intento=" + encodeURIComponent(bInf.getAttribute("data-informe"))); return; }

    const bVer = ev.target.closest("[data-ver]");
    if (bVer) { alternarVideosModulo(bVer, MODULOS_PINTADOS[bVer.getAttribute("data-ver")]); return; }

    const bDoc = ev.target.closest("[data-doc]");
    if (bDoc) {
      const id = bDoc.getAttribute("data-doc");
      abrirDocumentoMaestro(id, (MODULOS_PINTADOS[id] || {}).nombre || id);
      return;
    }

    const fila = ev.target.closest(".vid-fila");
    if (fila) {
      const v = JSON.parse(fila.getAttribute("data-video"));
      // Desde el módulo se abre el mismo reproductor del catálogo: una sola
      // pieza que mantiene el progreso, no una segunda forma de ver videos.
      abrirVideo(v);
    }
  });
}

/* El documento maestro es un markdown generado por la IA a partir de los videos
   del módulo: es el material de repaso antes del examen. Se lee aquí dentro.

El PDF lo genera el servidor y devuelve una URL de Drive. El iframe de
HtmlService no puede forzar una descarga, así que se ofrece como enlace:
intentar `window.open` sin gesto directo lo bloquea el navegador.
/
async function descargarInformePDF(intentoId, boton) {
  const estado = document.getElementById("inf-pdf-estado");
  boton.disabled = true;
  boton.textContent = "Generando…";
  if (estado) estado.textContent = "";

  try {
    const r = await api("informe_pdf", { intentoId: intentoId }, { callar: true });
    boton.textContent = "Descargar informe en PDF";
    boton.disabled = false;
    if (estado && r && r.url) {
      estado.innerHTML = 'Listo: <a href="' + esc(r.url) + '" target="_blank" rel="noopener">' +
        esc(r.nombre || "abrir el PDF") + "</a>";
    }
    brindis("Informe generado.", "ok");
  } catch (e) {
    boton.disabled = false;
    boton.textContent = "Descargar informe en PDF";
    if (estado) estado.textContent = e.message;
    brindis(e.message, "err", 5000);
  }
}

/* =====================================================================
   VISTA 8 · MIS NOTAS Y MI PROGRESO
   =====================================================================
   Responde de un vistazo tres preguntas que hoy nadie podía contestar
   sin abrir la hoja de cálculo: cuánto llevo certificado, cómo voy de
   nota, y si estoy mejorando o empeorando.

   La evolución se dibuja en SVG a mano, sin librería: son entre 3 y 20
   puntos y cargar una librería de gráficos para eso cuesta más de lo que
   pesa el portal entero.
   =====================================================================

Línea temporal de notas en SVG.

El eje va SIEMPRE de 0 a 100 aunque las notas estén todas entre 70 y 90:
ajustar el eje a los datos exagera las diferencias y hace parecer un
desplome lo que son tres puntos porcentuales. En una nota, la escala
absoluta es la que significa algo.
/
function graficoEvolucion(hist) {
  const puntos = hist.slice(-20);
  const An = 100, Al = 42, m = 4;          // viewBox; se escala con CSS
  const paso = puntos.length > 1 ? (An - m * 2) / (puntos.length - 1) : 0;
  const y = function (p) { return Al - m - ((Math.max(0, Math.min(100, p)) / 100) * (Al - m * 2)); };

  const coords = puntos.map(function (h, i) {
    return { x: m + paso * i, y: y(h.porcentaje || 0), h: h };
  });
  const linea = coords.map(function (c, i) {
    return (i ? "L" : "M") + c.x.toFixed(1) + " " + c.y.toFixed(1);
  }).join(" ");

  return '<div class="not-grafico">' +
    '<svg viewBox="0 0 ' + An + " " + Al + '" preserveAspectRatio="none" role="img" ' +
      'aria-label="Evolución de tus notas: ' +
      puntos.map(function (h) { return Math.round(h.porcentaje || 0) + "%"; }).join(", ") + '">' +
      // Referencia del 80: es la línea que certifica, y sin ella el gráfico no
      // dice si vas bien, solo si subes o bajas.
      '<line x1="' + m + '" y1="' + y(80).toFixed(1) + '" x2="' + (An - m) +
        '" y2="' + y(80).toFixed(1) + '" class="not-g-corte"/>' +
      '<path d="' + linea + '" class="not-g-linea"/>' +
      coords.map(function (c) {
        return '<circle cx="' + c.x.toFixed(1) + '" cy="' + c.y.toFixed(1) + '" r="1.4" class="not-g-punto"/>';
      }).join("") +
    "</svg>" +
    '<div class="not-g-pies"><span>' + esc(puntos[0].fecha || "") + "</span>" +
      '<span class="mut">línea: 80% certifica</span>' +
      "<span>" + esc(puntos[puntos.length - 1].fecha || "") + "</span></div>" +
  "</div>";
}

/**
Panel lateral genérico, con el mismo aspecto que el del reproductor.
Se separa del panel de video porque aquel guarda progreso al cerrarse y
arrastra un temporizador; para mostrar una lista de dispositivos o un
documento no hace falta nada de eso.

Segundos a algo que se lea de un vistazo. */
function tiempoLegible(seg) {
  const s = Math.max(0, Math.round(parseFloat(seg) || 0));
  if (s < 60) return s ? s + " s" : "—";
  const h = Math.floor(s / 3600), m = Math.round((s % 3600) / 60);
  if (!h) return m + " min";
  return h + " h" + (m ? " " + m + " min" : "");
}

/* El rótulo del mes lo pone el navegador y no el servidor: así sale en el idioma
   de quien mira sin arrastrar una lista de nombres de mes por el código.

El listado por persona de la pestaña Panel.

Se pide aparte del panel y no dentro de `panel_admin`: recorre dos hojas
enteras y agrupa por persona, y meterlo en la llamada que ya trae el estado del
sistema haría esperar por los tiempos a quien entra a ver si hay incidencias.
Si falla, la pestaña sigue sirviendo para todo lo demás.

El contenedor llega por parámetro porque hay dos —el del Panel y el de la vista
de supervisión— y un administrador puede haber visitado los dos: con un mismo
identificador en los dos sitios, el segundo repintado se iría al primero.
/
async function pintarTiemposPanel(idContenedor) {
  const id = idContenedor || "adm-tiempos";
  const cont = document.getElementById(id);
  if (!cont) return;
  let d;
  try {
    d = await api("tiempos_resumen", {}, { silencioso: true, callar: true });
  } catch (e) {
    cont.innerHTML = '<section class="adm-caja"><h2>Tiempo dedicado</h2>' +
      '<p class="mut">No se pudo calcular: ' + esc(e.message) + "</p></section>";
    return;
  }
  if (document.getElementById(id) !== cont) return;   // se repintó la vista mientras llegaba

  cont.innerHTML = '<section class="adm-caja"><h2>Tiempo dedicado · ' +
      esc(mesLegible(d.mes)) + "</h2>" +
    ((d.personas || []).length
      ? '<p class="mut" style="font-size:12.5px">Toca una persona para ver su informe completo.</p>' +
        comparativaTiemposHTML(d)
      : '<p class="mut">Nadie ha reproducido videos en el portal este mes. La medición empieza a ' +
        "contar el día en que se instala.</p>") +
    "</section>";
  cont.querySelectorAll("[data-tmp-persona]").forEach(function (b) {
    b.addEventListener("click", function () { verInformeTiempos(b.getAttribute("data-tmp-persona")); });
  });
}

/* ---------- Sugerencias ----------

mm:ss o h:mm:ss, según haga falta. */
function formatoReloj(segundos) {
  const s = Math.max(0, Math.floor(segundos || 0));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60;
  const dos = function (n) { return (n < 10 ? "0" : "") + n; };
  return h > 0 ? h + ":" + dos(m) + ":" + dos(r) : m + ":" + dos(r);
}

/* Salta el reproductor a un segundo concreto. Cada plataforma tiene su forma;
   la que no la tenga abre el enlace con el tiempo, que es lo único posible.
